(function(){"use strict";var OPEN_CLASS="is-open";function getItems(){return document.querySelectorAll(".home-header__nav-item--has-dropdown")}function getLink(item){return item.querySelector(".home-header__nav-link")}function closeAll(except){getItems().forEach(function(item){if(item!==except){item.classList.remove(OPEN_CLASS);var link=getLink(item);if(link)link.setAttribute("aria-expanded","false")}})}function openItem(item){closeAll(item);item.classList.add(OPEN_CLASS);var link=getLink(item);if(link)link.setAttribute("aria-expanded","true")}function closeItem(item){item.classList.remove(OPEN_CLASS);var link=getLink(item);if(link)link.setAttribute("aria-expanded","false")}function toggleItem(item){if(item.classList.contains(OPEN_CLASS)){closeItem(item)}else{openItem(item)}}function getFocusableMenuItems(item){var dropdown=item.querySelector(".home-header__dropdown");if(!dropdown)return[];return Array.prototype.slice.call(dropdown.querySelectorAll('a[role="menuitem"]'))}function bootstrap(){var nodes=getItems();if(!nodes.length)return false;if(document.body.getAttribute("data-header-dropdowns-bootstrapped")==="1")return true;document.body.setAttribute("data-header-dropdowns-bootstrapped","1");nodes.forEach(function(item){var link=item.querySelector(".home-header__nav-link");if(link)link.setAttribute("aria-expanded","false");var caret=item.querySelector(".home-header__nav-caret");var dropdown=item.querySelector(".home-header__dropdown");if(!link||!dropdown)return;link.addEventListener("click",function(e){var isCoarse=window.matchMedia("(pointer: coarse)").matches;var isOpen=item.classList.contains(OPEN_CLASS);if(isCoarse){if(!isOpen){e.preventDefault();toggleItem(item)}}});link.addEventListener("keydown",function(e){if(e.key==="Enter"||e.key===" "){e.preventDefault();toggleItem(item);if(item.classList.contains(OPEN_CLASS)){var menuItems=getFocusableMenuItems(item);if(menuItems.length)menuItems[0].focus()}}if(e.key==="Escape"){closeItem(item);link.focus()}if(e.key==="ArrowDown"){e.preventDefault();openItem(item);var menuItems=getFocusableMenuItems(item);if(menuItems.length)menuItems[0].focus()}});var hoverTimer=null;item.addEventListener("mouseenter",function(){var isCoarse=window.matchMedia("(pointer: coarse)").matches;if(isCoarse)return;clearTimeout(hoverTimer);link.setAttribute("aria-expanded","true")});item.addEventListener("mouseleave",function(){var isCoarse=window.matchMedia("(pointer: coarse)").matches;if(isCoarse)return;hoverTimer=setTimeout(function(){if(!item.classList.contains(OPEN_CLASS)){link.setAttribute("aria-expanded","false")}},100)});if(dropdown){dropdown.addEventListener("keydown",function(e){var menuItems=getFocusableMenuItems(item);var focused=document.activeElement;var idx=menuItems.indexOf(focused);if(e.key==="ArrowDown"){e.preventDefault();var next=menuItems[idx+1]||menuItems[0];if(next)next.focus()}else if(e.key==="ArrowUp"){e.preventDefault();var prev=menuItems[idx-1]||menuItems[menuItems.length-1];if(prev)prev.focus()}else if(e.key==="Escape"){closeItem(item);link.focus()}else if(e.key==="Tab"){closeItem(item)}})}});document.addEventListener("click",function(e){var clickedInside=e.target.closest(".home-header__nav-item--has-dropdown");if(!clickedInside){closeAll(null)}});document.addEventListener("keydown",function(e){if(e.key==="Escape"){closeAll(null)}});return true}if(!bootstrap()){var tries=0;var poll=setInterval(function(){tries++;if(bootstrap()||tries>50){clearInterval(poll)}},100)}})();
